using Intranet.Entity;using Intranet.Service;
namespace Intranet.Api.Tests;
public sealed class PcpAnaliticasTests {
 [Fact]public void PcpEndpointsRequireExistingLogisticsQueryPermission()=>Assert.Equal(new[]{"orders.query"},Intranet.Api.Security.PortalAccessFilter.Required("PcpAnaliticas","Send","POST"));
 private static AnalisisRbOperations Current()=>new("J1907","B3392","T-SHIRT","0","0",[],[new("CS","10","CUELLO","001","100001","0","Coser cuello","","","","","",1.2m){SectorName="COSTURA"},new("CS","20","MANGA","002","100002","0","Coser manga","","","","","",2.3m){SectorName="COSTURA"}]);
 private static PcpSend Request(AnalisisRbOperations data)=>new(){RequestId=Guid.NewGuid(),Np=data.Np,Tariff=data.Tariff,Variant=data.SelectedVariant,Sector="CS",Operations=data.Rows.Select(PcpAnaliticasService.Snapshot).ToArray(),Selected=data.Rows.Select(PcpAnaliticasService.Snapshot).ToArray()};
 [Fact]public void AllOperationsAreComplete(){var current=Current();var selection=PcpAnaliticasService.Validate(Request(current),current);Assert.True(selection.SectorAnalysis.IsComplete);Assert.Equal(3.5m,selection.Operations.Sum(x=>x.StandardTime));Assert.Equal(2,selection.Operations.Count);}
 [Fact]public void SubsetIsPartial(){var current=Current();var request=Request(current);request.Selected=request.Selected.Take(1).ToArray();var selection=PcpAnaliticasService.Validate(request,current);Assert.False(selection.SectorAnalysis.IsComplete);Assert.Equal(1.2m,selection.Operations.Sum(x=>x.StandardTime));}
 [Fact]public void EmptyAndDuplicatedSelectionAreRejected(){var current=Current();var request=Request(current);request.Selected=[];Assert.Throws<ArgumentException>(()=>PcpAnaliticasService.Validate(request,current));request.Selected=[request.Operations[0],request.Operations[0]];Assert.Throws<ArgumentException>(()=>PcpAnaliticasService.Validate(request,current));}
 [Fact]public void ChangedTariffIsRejected(){var current=Current();var request=Request(current);request.Operations=request.Operations.Select(x=>x with{StandardTime=99}).ToArray();Assert.Throws<ArgumentException>(()=>PcpAnaliticasService.Validate(request,current));}
 [Fact]public void LogisticsCannotChangeReceivedOperations(){var current=Current();var request=Request(current);request.Selected=request.Selected.Take(1).ToArray();var snapshot=PcpAnaliticasService.Validate(request,current);var s=snapshot.SectorAnalysis;var entry=new PcpEntry(1,"J1907","CS","B3392","0",1,false,"E",2,1,3.5m,1.2m,"PCP",DateTime.UtcNow,null,snapshot);var analysis=new AnalisisRbSave{Source=new("J1907",438),UsedTime=1.2m,SectorAnalysis=s,PartialSelection=new(s.Tariff,s.Variant,s.Sector,s.SectorName,s.TotalTime,snapshot.Operations)};PcpAnaliticasService.ValidateForAnalysis(analysis,entry);analysis.UsedTime=3.5m;Assert.Throws<ArgumentException>(()=>PcpAnaliticasService.ValidateForAnalysis(analysis,entry));}
 [Fact]public void ReplacedPreparationCannotBeUsed(){var current=Current();var snapshot=PcpAnaliticasService.Validate(Request(current),current);var entry=new PcpEntry(1,"J1907","CS","B3392","0",1,true,"S",2,2,3.5m,3.5m,"PCP",DateTime.UtcNow,null,snapshot);Assert.Throws<ArgumentException>(()=>PcpAnaliticasService.ValidateForAnalysis(new(){Source=new("J1907",438),UsedTime=3.5m,SectorAnalysis=snapshot.SectorAnalysis},entry));}
}
